id: sqlserver
title: SQL Server
kind: catalog
inputs:
  database: { description: "The database whose tables are loaded, such as ERP" }
ask: run it
read: columns
names: { parts: 3, caseSensitive: false }
types:
  - { match: "^bit$", logicalType: boolean }
  - {
      match: "^decimal\\((\\d+),(\\d+)\\)$",
      logicalType: number,
      options: { precision: $1, scale: $2 },
    }
  - { match: "^varchar\\((\\d+)\\)$", logicalType: string, options: { maxLength: $1 } }
sources:
  - { url: "https://example.com/sql-server/information-schema-columns", read: 2026-11-12 }
